//! The OpenAPI 3.1 description of the REST API, generated by `scripts/gen-openapi.py` into
//! `crates/server/openapi.yaml` and `openapi.json` (the same document) and served as is.

use std::sync::LazyLock;

use axum::http::{HeaderMap, HeaderValue, StatusCode, header};
use axum::response::{IntoResponse, Response};
use sha2::{Digest, Sha256};

pub const SPEC_YAML: &str = include_str!("../../openapi.yaml");
pub const SPEC_JSON: &str = include_str!("../../openapi.json");

fn etag(kind: &str, body: &str) -> String {
    format!("W/\"{kind}-{}\"", hex::encode(&Sha256::digest(body.as_bytes())[..8]))
}

static YAML_ETAG: LazyLock<String> = LazyLock::new(|| etag("y", SPEC_YAML));
static JSON_ETAG: LazyLock<String> = LazyLock::new(|| etag("j", SPEC_JSON));

/// The document, cacheable (revalidated by its ETag after five minutes); public.
fn serve(headers: &HeaderMap, body: &'static str, content_type: &'static str, etag: &str) -> Response {
    let tag = HeaderValue::from_str(etag).unwrap_or_else(|_| HeaderValue::from_static("W/\"spec\""));
    let cache = HeaderValue::from_static("public, max-age=300");
    let fresh = headers.get(header::IF_NONE_MATCH).and_then(|v| v.to_str().ok()).is_some_and(|v| v.split(',').any(|t| t.trim() == etag || t.trim() == "*"));
    if fresh {
        return (StatusCode::NOT_MODIFIED, [(header::ETAG, tag), (header::CACHE_CONTROL, cache)]).into_response();
    }
    ([(header::CONTENT_TYPE, HeaderValue::from_static(content_type)), (header::ETAG, tag), (header::CACHE_CONTROL, cache)], body).into_response()
}

/// `GET /api/openapi.yaml`
pub async fn yaml(headers: HeaderMap) -> Response {
    serve(&headers, SPEC_YAML, "application/yaml; charset=utf-8", &YAML_ETAG)
}

/// `GET /api/openapi.json` (what the in-app API reference reads)
pub async fn json(headers: HeaderMap) -> Response {
    serve(&headers, SPEC_JSON, "application/json", &JSON_ETAG)
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    const METHODS: [&str; 5] = ["get", "post", "put", "patch", "delete"];

    /// The `.route("path", method_router)` calls of a router's source: (path, methods).
    fn routes(src: &str) -> Vec<(String, Vec<&'static str>)> {
        let mut out = Vec::new();
        let mut rest = src;
        while let Some(i) = rest.find(".route(\"") {
            rest = &rest[i + 8..];
            let end = rest.find('"').expect("end of the path");
            let path = rest[..end].to_string();
            // the method router: up to the parenthesis that closes this .route(
            let mut depth = 1;
            let mut close = rest.len();
            for (j, c) in rest.char_indices().skip(end + 1) {
                match c {
                    '(' => depth += 1,
                    ')' => {
                        depth -= 1;
                        if depth == 0 {
                            close = j;
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let call = &rest[end + 1..close];
            // get(handler).post(handler), axum::routing::post(handler): a method name called
            // right away (handler names like `projects::delete` are never called here)
            let methods: Vec<&'static str> = METHODS
                .into_iter()
                .filter(|m| call.match_indices(&format!("{m}(")).any(|(at, _)| at == 0 || !call[..at].ends_with(|c: char| c.is_alphanumeric() || c == '_')))
                .collect();
            assert!(!methods.is_empty(), "no method found for {path}: {call}");
            out.push((path, methods));
            rest = &rest[close..];
        }
        out
    }

    fn section<'a>(src: &'a str, start: &str, end: &str) -> &'a str {
        let from = src.find(start).unwrap_or_else(|| panic!("{start} not found"));
        let s = &src[from..];
        &s[..s.find(end).unwrap_or(s.len())]
    }

    /// Every route the API serves is documented with the same methods, and nothing else is: the
    /// routers of routes/mod.rs, routes/security.rs and sso/mod.rs (SAML routes included, whatever
    /// the build's features).
    #[test]
    fn spec_covers_every_route() {
        let mut routed = BTreeSet::new();
        for (src, start, end) in [
            (include_str!("mod.rs"), "pub fn api()", "pub fn router("),
            (include_str!("security.rs"), "pub fn routes()", "\n}\n"),
            (include_str!("../sso/mod.rs"), "pub fn routes()", "\n}\n"),
        ] {
            for (path, methods) in routes(section(src, start, end)) {
                for m in methods {
                    assert!(routed.insert((path.clone(), m)), "{m} {path} routed twice");
                }
            }
        }
        assert!(routed.len() > 200, "only {} operations parsed", routed.len());

        let spec: serde_json::Value = serde_json::from_str(super::SPEC_JSON).expect("openapi.json is JSON");
        assert_eq!(spec["openapi"], "3.1.0");
        let mut documented = BTreeSet::new();
        for (path, item) in spec["paths"].as_object().expect("paths") {
            for m in METHODS {
                if item.get(m).is_some() {
                    documented.insert((path.clone(), m));
                }
            }
        }
        let missing: Vec<String> = routed.difference(&documented).map(|(p, m)| format!("{} {p}", m.to_uppercase())).collect();
        let stale: Vec<String> = documented.difference(&routed).map(|(p, m)| format!("{} {p}", m.to_uppercase())).collect();
        assert!(missing.is_empty(), "undocumented routes (add them to scripts/gen-openapi.py and run it): {missing:?}");
        assert!(stale.is_empty(), "documented routes that don't exist (remove them from scripts/gen-openapi.py and run it): {stale:?}");

        // the YAML is the same document
        assert!(super::SPEC_YAML.contains("\nopenapi: 3.1.0\n"));
        for (path, _) in &documented {
            assert!(super::SPEC_YAML.contains(&format!("\n  {path}:\n")), "{path} missing from openapi.yaml: run scripts/gen-openapi.py");
        }
    }

    #[test]
    fn route_parser_reads_method_chains() {
        let src = r#".route("/a/{id}", get(x::get).patch(x::update).delete(x::delete))
            .route("/b", axum::routing::post(saml::acs)).route("/c", get(saml::metadata));"#;
        assert_eq!(
            routes(src),
            vec![("/a/{id}".to_string(), vec!["get", "patch", "delete"]), ("/b".to_string(), vec!["post"]), ("/c".to_string(), vec!["get"])]
        );
    }
}
